189	  0% { transform: scale(0.6); }
190	  60% { transform: scale(1.35); }
191	  100% { transform: scale(1); }
192	}
193	@keyframes float-up {
194	  0% { opacity: 0; transform: translate(-50%, 14px) scale(0.8); }
195	  18% { opacity: 1; transform: translate(-50%, 0) scale(1.12); }
196	  100% { opacity: 0; transform: translate(-50%, -96px) scale(1); }
197	}
198	@keyframes glow-green {
199	  0% { box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35); }
200	  28% { box-shadow: 0 0 0 4px var(--green), 0 0 38px 10px rgba(61, 220, 132, 0.55); }
201	  100% { box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35); }
202	}
203	@keyframes shake {
204	  10%, 90% { transform: translateX(-3px); }
205	  20%, 80% { transform: translateX(5px); }
206	  30%, 50%, 70% { transform: translateX(-9px); }
207	  40%, 60% { transform: translateX(9px); }
208	}
209	
210	/* ---------- Email: looks like an inbox message ---------- */
211	#message.card { padding: 0; background: none; }
212	.email {
213	  background: #f7f9fb; color: #1b2a3a;
214	  border-radius: 14px; overflow: hidden;
215	  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
216	}
217	.email::before {
218	  content: "INBOX";
219	  display: block; padding: 10px 18px;
220	  background: #dfe7ee; color: #45566a;
221	  font-size: 13px; font-weight: 600; letter-spacing: 1px;
222	}
223	.email-head {
224	  display: flex; align-items: flex-start; gap: 12px;
225	  padding: 14px 16px; border-bottom: 1px solid #e3e9ef;
226	}
227	.avatar {
228	  flex: 0 0 auto; width: 42px; height: 42px; border-radius: 50%;
229	  background: var(--navy-2); color: #fff;
230	  display: flex; align-items: center; justify-content: center;
231	  font-size: 18px; font-weight: 800;
232	}
233	.email-who { flex: 1 1 auto; min-width: 0; }
234	.email-who .from { margin: 0; font-size: 14px; color: #5b6b7b; overflow-wrap: anywhere; }
235	.email-who .from b { color: #1b2a3a; }
236	.email-who .subject { margin: 3px 0 0; font-size: 15px; font-weight: 600; color: #1b2a3a; overflow-wrap: anywhere; }
237	.email-time { flex: 0 0 auto; margin: 2px 0 0; font-size: 12px; color: #7b8a99; white-space: nowrap; }
238	
239	.email .body { margin: 0; padding: 18px; line-height: 1.6; }
240	
241	.email-actions {
242	  display: flex; gap: 10px;
243	  padding: 12px 16px; border-top: 1px solid #e3e9ef; background: #eef3f7;
244	}
245	.email-actions button,
246	.email-actions button:disabled {
247	  font-size: 14px; padding: 8px 16px; border-radius: 8px;
248	  background: #e1e8ee; color: #9aa8b5; border: 1px solid #d3dce4;
249	  opacity: 1; cursor: not-allowed;
250	}
251	
252	/* ---------- Text message: looks like a phone ---------- */
253	.sms {
254	  width: 320px; max-width: 100%; margin: 0 auto; padding: 14px 16px 28px;
255	  background: #101826; border: 3px solid #2b3a4f; border-radius: 36px;
256	  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
257	}
258	.sms::before {
259	  content: ""; display: block; width: 90px; height: 6px;
260	  margin: 0 auto 12px; background: #2b3a4f; border-radius: 3px;
261	}
262	
263	/* Phone status bar: time, signal bars, battery */
264	.status-bar {
265	  display: flex; align-items: center; justify-content: space-between;
266	  padding: 0 4px 14px; font-size: 13px; font-weight: 600; color: var(--text);
267	}
268	.sb-right { display: flex; align-items: center; gap: 7px; }
269	.signal { display: flex; align-items: flex-end; gap: 2px; height: 11px; }
270	.signal i { width: 3px; background: var(--text); border-radius: 1px; }
271	.signal i:nth-child(1) { height: 4px; }
272	.signal i:nth-child(2) { height: 6px; }
273	.signal i:nth-child(3) { height: 9px; }
274	.signal i:nth-child(4) { height: 11px; }
275	.battery {
276	  position: relative; width: 25px; height: 13px;
277	  border: 1.5px solid var(--text); border-radius: 3px; padding: 2px;
278	}
279	.battery::after {
280	  content: ""; position: absolute; right: -4px; top: 3.5px;
281	  width: 2px; height: 5px; background: var(--text); border-radius: 0 2px 2px 0;
282	}
283	.bat-fill { display: block; height: 100%; width: 72%; background: var(--green); border-radius: 1px; }
284	
285	.sms .label { text-align: center; font-size: 13px; color: var(--muted); margin: 0 0 14px; }
286	.sms .label b { display: block; font-size: 16px; color: var(--text); }
287	.bubble {
288	  background: #e9edf2; color: #1b2a3a;
289	  padding: 12px 14px; border-radius: 18px 18px 18px 4px;
290	  line-height: 1.5; margin: 0; max-width: 85%;
291	}
292	
293	/* Links are buttons on purpose: they only preview, never open anything */
294	.link {
295	  display: flex; flex-wrap: wrap; align-items: center; gap: 6px 10px;
296	  margin: 0; padding: 0 18px 18px;
297	}
298	.link-chip,
299	.link-chip:hover {
300	  font: inherit; font-weight: 600; text-align: left;
301	  padding: 0; margin: 0; border: 0; border-radius: 3px;
302	  background: none; color: #1a5fd0;
303	  text-decoration: underline; text-underline-offset: 3px;
304	  cursor: help; transform: none; box-shadow: none;
305	  overflow-wrap: anywhere;
306	}
307	.link-chip:focus-visible { outline: 2px solid #1a5fd0; outline-offset: 3px; }
308	.link-hint {
309	  font-size: 12px; font-weight: 600; color: #7b8a99;
310	  padding: 2px 8px; border-radius: 999px; background: #e7edf2;
311	}
312	.hint-tap { display: none; }
313	@media (hover: none) {
314	  .hint-hover { display: none; }
315	  .hint-tap { display: inline; }
316	}
317	.sms .link { padding: 10px 0 0; }
318	.sms .link-chip { font-family: monospace; font-weight: 400; color: var(--teal); }
319	.sms .link-chip:focus-visible { outline-color: var(--teal); }
320	.sms .link-hint { background: #1d2a3d; color: var(--muted); }
321	
322	/* The popup that shows a link's real destination */
323	.link-peek {
324	  position: fixed; z-index: 1000;
325	  width: max-content; max-width: min(360px, calc(100vw - 24px));
326	  padding: 10px 12px; border-radius: 10px;
327	  background: #0d1b2e; color: var(--text);
328	  border: 1px solid #2b3a4f;
329	  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.45);
330	  font-size: 13px; line-height: 1.45;
331	  animation: peek-in 0.12s ease-out;
332	}
333	.link-peek p { margin: 0; }
334	.peek-title { color: var(--muted); font-weight: 600; margin-bottom: 4px !important; }
335	.peek-url { font-family: monospace; font-size: 14px; overflow-wrap: anywhere; color: #c9d6e2; }
336	.peek-sub { color: inherit; }
337	.peek-domain { color: #ffd166; background: rgba(255, 209, 102, 0.12); padding: 0 2px; border-radius: 3px; }
338	.peek-tip { margin-top: 6px !important; color: var(--muted); font-size: 12px; }
339	.peek-tip b { color: var(--text); }
340	@keyframes peek-in {
341	  from { opacity: 0; transform: translateY(4px); }
342	}
343	.link-reveal { margin-bottom: 0; }
344	
345	.answers { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
346	.answer.phish { background: var(--red); color: white; }
347	.answer.legit { background: var(--green); color: var(--navy); }
348	
349	#btn-next, #btn-home { display: block; margin: 0 auto; }
350	#end-screen { text-align: center; }
351	
352	/* ---------- Badge reveal ---------- */
353	.badge-reveal { position: relative; padding: 10px 0 2px; }
354	.badge-art {
355	  font-size: 96px; line-height: 1.1;
356	  animation: badge-drop 1.1s cubic-bezier(0.2, 0.75, 0.3, 1) both;
357	}
358	.badge-name {
359	  margin: 2px 0 0; font-size: 26px; font-weight: 800; color: var(--teal);
360	  animation: fade-rise 0.5s ease-out 0.75s both;
361	}
362	.badge-master {
363	  display: inline-block; margin: 14px 0 0; padding: 8px 16px;
364	  border: 2px solid var(--teal); border-radius: 999px;
365	  background: rgba(45, 224, 196, 0.1);
366	  font-weight: 700; color: var(--text);
367	  animation: fade-rise 0.5s ease-out 1.1s both;
368	}
369	
370	@keyframes badge-drop {
371	  0% { opacity: 0; transform: translateY(-170px) scale(0.4) rotate(0deg); }
372	  55% { opacity: 1; transform: translateY(0) scale(1.28) rotate(360deg); }
373	  70% { transform: translateY(0) scale(0.92) rotate(372deg); }
374	  85% { transform: translateY(0) scale(1.07) rotate(354deg); }
375	  100% { opacity: 1; transform: translateY(0) scale(1) rotate(360deg); }
376	}
377	@keyframes fade-rise {
378	  0% { opacity: 0; transform: translateY(12px); }
379	  100% { opacity: 1; transform: translateY(0); }
380	}
381	
382	/* Confetti burst (pure CSS/JS, no libraries) */
383	.confetti { position: absolute; left: 0; right: 0; top: 0; height: 0; pointer-events: none; }
384	.confetti-bit {
385	  position: absolute; top: 0; width: 9px; height: 14px; border-radius: 2px;
386	  animation-name: confetti-fall; animation-timing-function: ease-in; animation-fill-mode: forwards;
387	}
388	@keyframes confetti-fall {
389	  0% { opacity: 1; transform: translate(0, -10px) rotate(0deg); }
390	  100% { opacity: 0; transform: translate(var(--dx), 300px) rotate(var(--rot)); }
391	}
392	
393	/* ---------- End of run recap ---------- */
394	.recap { text-align: left; }
395	.recap h3 { margin: 0 0 10px; font-size: 16px; color: var(--text); }
396	.recap ul { margin: 0; padding-left: 20px; }
397	.recap li { margin: 7px 0; color: var(--muted); line-height: 1.45; }
398	.recap .count { color: var(--teal); font-weight: 700; }
399	.recap .clean { margin: 0; font-weight: 600; color: var(--green); }
400	
401	.leaderboard h3 { margin-top: 0; }
402	.leaderboard li { margin: 6px 0; }
403	.leaderboard span { float: right; color: var(--muted); }
404	.leaderboard .empty { color: var(--muted); list-style: none; margin-left: -20px; }
405	
406	/* ---------- Phone-sized screens ---------- */
407	@media (max-width: 430px) {
408	  header { padding: 20px 14px 6px; }
409	  header h1 { font-size: 34px; }
410	  .logo { width: 92px; }
411	  main { padding: 12px; }
412	
413	  .mode { padding: 14px 4px; font-size: 14px; }
414	  .mode small { font-size: 11px; }
415	  .mission-buttons { flex-direction: column; }
416	  .mission-buttons button { width: 100%; }
417	
418	  .dot { width: 12px; height: 12px; }
419	  .streak { font-size: 13px; }
420	  .dots { gap: 6px; }
421	  .run-right { gap: 6px; }
422	  .contacts-toggle { font-size: 12px; padding: 5px 9px; }
423	  .contacts-table { font-size: 13px; }
424	  .pop-score { font-size: 34px; }
425	  .reaction { font-size: 17px; padding: 10px 12px; margin-bottom: 12px; }
426	
427	  .email-head { padding: 12px; gap: 10px; }
428	  .avatar { width: 36px; height: 36px; font-size: 16px; }
429	  .email-who .subject { font-size: 14px; }
430	  .email .body { padding: 14px; }
431	  .link { padding: 0 14px 14px; }
432	  .email-actions { padding: 10px 12px; }
433	  .email-actions button, .email-actions button:disabled { padding: 7px 12px; font-size: 13px; }
434	
435	  .badge-art { font-size: 74px; }
436	  .badge-name { font-size: 22px; }
437	}
438	
439	/* ---------- Respect reduced motion ---------- */
440	@media (prefers-reduced-motion: reduce) {
441	  *, *::before, *::after {
442	    animation-duration: 0.001ms !important;
443	    animation-delay: 0ms !important;
444	    animation-iteration-count: 1 !important;
445	    transition-duration: 0.001ms !important;
446	  }
447	  #message.is-correct .email,
448	  #message.is-correct .sms { animation: none; box-shadow: 0 0 0 4px var(--green), 0 10px 30px rgba(0, 0, 0, 0.35); }
449	  #message.is-wrong { animation: none; }
450	  #message.is-wrong .email,
451	  #message.is-wrong .sms { box-shadow: 0 0 0 4px var(--red), 0 10px 30px rgba(0, 0, 0, 0.35); }
452	  .dot.correct, .dot.wrong { animation: none; }
453	  .reaction { animation: none; }
454	  .hook-rig { display: none; }
455	}
456	
457	/* ---------- Fish cursor (home screen only, see fish-cursor.js) ---------- */
458	body.fish-mode, body.fish-mode * { cursor: none !important; }
459	.fish-cursor {
460	  position: fixed; left: 0; top: 0; z-index: 9999;
461	  width: 50px; height: 36px; pointer-events: none;
462	  transform-origin: 46px 18px; opacity: 0;
463	  transition: opacity 0.2s ease;
464	  filter: drop-shadow(0 3px 6px rgba(0, 0, 0, 0.35));
465	}
466	.fish-cursor svg { display: block; overflow: visible; }
467	.fish-tail {
468	  transform-origin: 14px 18px;
469	  animation: fish-wag var(--wag, 0.6s) ease-in-out infinite alternate;
470	}
471	.fish-cursor.gulp svg { animation: fish-gulp 0.3s ease; }
472	@keyframes fish-wag {
473	  from { transform: rotate(-16deg); }
474	  to   { transform: rotate(16deg); }
475	}
476	@keyframes fish-gulp {
477	  40% { transform: scale(1.25, 0.85); }
478	}
479	.fish-bubble {
480	  position: fixed; z-index: 9998; pointer-events: none;
481	  border-radius: 50%; border: 1.5px solid rgba(185, 255, 241, 0.75);
482	  background: radial-gradient(circle at 30% 30%, rgba(255, 255, 255, 0.6), rgba(45, 224, 196, 0.08) 60%);
483	  transform: translate(-50%, -50%);
484	  animation: bubble-rise 1.2s ease-out forwards;
485	}
486	.fish-bubble.burst { animation-duration: 0.8s; }
487	@keyframes bubble-rise {
488	  from { opacity: 0.9; transform: translate(-50%, -50%) scale(0.6); }
489	  to   { opacity: 0; transform: translate(calc(-50% + var(--drift)), calc(-50% - 60px)) scale(1.1); }
490	}
491

file.content:
/* PhishSense colors: navy + teal, matching the logo */
:root {
  --navy: #0a1a33;
  --navy-2: #123a5c;
  --teal: #2de0c4;
  --text: #e9f1f7;
  --muted: #9fb7c9;
  --red: #ff5d6c;
  --green: #3ddc84;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: "Inter", Arial, sans-serif;
  background: var(--navy);
  color: var(--text);
}

header { text-align: center; padding: 32px 16px 8px; }
header h1 { margin: 0; font-size: 44px; font-weight: 800; }
header h1 span { color: var(--teal); }
.logo { width: 120px; height: auto; display: block; margin: 0 auto 8px; }
.tagline { margin: 4px 0 0; color: var(--muted); letter-spacing: 3px; text-transform: uppercase; font-size: 13px; }

main { max-width: 640px; margin: 0 auto; padding: 16px; }
.hidden { display: none !important; }

/* Start screen */
.intro { text-align: center; color: var(--muted); margin: 4px 0 0; }
.step-label { margin: 22px 0 8px; font-weight: 600; color: var(--text); }
.step-label + input { margin-top: 0; }

/* Mission screen */
.briefing { margin-top: 8px; line-height: 1.6; color: var(--muted); }
.briefing p { margin: 0 0 10px; }
.briefing p:last-child { margin-bottom: 0; }
.briefing b { color: var(--text); }
.briefing-title { font-size: 13px; font-weight: 600; letter-spacing: 2px; text-transform: uppercase; color: var(--teal) !important; }
.mission-mode { font-size: 20px; font-weight: 800; color: var(--text); }
.facts { padding: 10px 14px; border-left: 3px solid var(--teal); background: rgba(45, 224, 196, 0.08); border-radius: 6px; }
.mission-buttons { display: flex; justify-content: space-between; gap: 12px; }
button.secondary { background: transparent; color: var(--text); border: 2px solid var(--navy-2); }

input {
  display: block; width: 100%; margin: 0; padding: 12px;
  border-radius: 10px; border: 1px solid var(--navy-2);
  background: var(--navy-2); color: var(--text); font-size: 16px;
}

button {
  font-family: inherit; font-size: 16px; font-weight: 600; cursor: pointer;
  border: none; border-radius: 10px; padding: 12px 18px;
  background: var(--teal); color: var(--navy);
}
button:disabled { opacity: 0.5; cursor: default; }

.modes { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
.mode { padding: 18px 8px; background: var(--navy-2); color: var(--text); border: 2px solid var(--teal); }
.mode small { color: var(--muted); font-weight: 400; }

.card { background: var(--navy-2); border-radius: 14px; padding: 18px; margin: 16px 0; }
.card.good { border-left: 6px solid var(--green); }
.card.bad { border-left: 6px solid var(--red); }

#progress { text-align: center; color: var(--muted); }
.loading { color: var(--muted); text-align: center; }

/* ---------- Run status: progress dots + streak ---------- */
.run-bar {
  display: flex; align-items: center; justify-content: space-between;
  gap: 12px; min-height: 26px; margin-top: 4px;
}
.dots { display: flex; gap: 8px; }
.dot {
  width: 14px; height: 14px; border-radius: 50%;
  background: transparent; border: 2px solid #2b4a68;
  transition: background 0.25s ease, border-color 0.25s ease, transform 0.25s ease;
}
.dot.current { border-color: var(--teal); transform: scale(1.2); }
.dot.correct { background: var(--green); border-color: var(--green); animation: dot-pop 0.4s ease; }
.dot.wrong { background: var(--red); border-color: var(--red); animation: dot-pop 0.4s ease; }

.streak { margin: 0; font-size: 14px; font-weight: 600; color: var(--teal); white-space: nowrap; }
.run-bar { flex-wrap: wrap; row-gap: 8px; }
.run-right { display: flex; align-items: center; gap: 10px; margin-left: auto; }

/* ---------- Trusted contacts (briefing card + play panel) ---------- */
.contacts-toggle {
  font-size: 13px; padding: 6px 12px; border-radius: 999px; white-space: nowrap;
  background: transparent; color: var(--text); border: 2px solid var(--navy-2);
}
.contacts-toggle:hover, .contacts-toggle.open { border-color: var(--teal); }
.contacts-toggle.open { background: rgba(45, 224, 196, 0.12); }

.contacts-title {
  margin: 0 0 10px; font-size: 13px; font-weight: 600;
  letter-spacing: 2px; text-transform: uppercase; color: var(--teal);
}
.contacts-panel { margin: 12px 0 4px; border: 1px solid #2b4a68; }
.contacts-table { width: 100%; border-collapse: collapse; font-size: 14px; }
.contacts-table th, .contacts-table td {
  text-align: left; vertical-align: top; padding: 8px 6px;
  border-bottom: 1px solid rgba(159, 183, 201, 0.18);
}
.contacts-table thead th {
  padding-top: 0; font-size: 12px; font-weight: 600; color: var(--muted);
}
.contacts-table tbody th { font-weight: 600; color: var(--text); }
.contacts-table tbody th small { display: block; font-weight: 400; font-size: 12px; color: var(--muted); }
.contact-domain, .contact-phone { display: block; font-family: monospace; font-size: 14px; color: var(--teal); overflow-wrap: anywhere; }
.contact-phone { color: var(--text); }
.contacts-tip { margin: 10px 0 0; font-size: 13px; color: var(--muted); }

/* ---------- Message area: glow, shake, floating score ---------- */
.message-wrap { position: relative; }
.pop-layer { position: absolute; inset: 0; pointer-events: none; overflow: visible; }
.pop-score {
  position: absolute; left: 50%; top: 24%;
  font-size: 40px; font-weight: 800; color: var(--green);
  text-shadow: 0 2px 12px rgba(10, 26, 51, 0.8);
  animation: float-up 1.3s ease-out forwards;
}

#message.is-correct .email,
#message.is-correct .sms { animation: glow-green 1.1s ease-out; }
#message.is-wrong { animation: shake 0.45s ease-in-out; }

/* ---------- Answer reactions ---------- */
/* Keeps a tilted card from adding a sideways scrollbar while the hook pulls it */
body { overflow-x: clip; }

#message.hook-anim { position: relative; z-index: 50; animation: none; }
#message.is-hooked .email,
#message.is-hooked .sms { box-shadow: 0 0 0 4px var(--red), 0 10px 30px rgba(0, 0, 0, 0.35); }
#message.is-cautious .email,
#message.is-cautious .sms { box-shadow: 0 0 0 3px rgba(255, 209, 102, 0.6), 0 10px 30px rgba(0, 0, 0, 0.35); }

.hook-rig {
  position: absolute; z-index: 60; width: 0; height: 0;
  pointer-events: none; transform-origin: 0 0; will-change: transform;
}
.hook-line {
  position: absolute; left: -1px; top: 0;
  width: 2px; height: var(--drop);
  background: #dfe7ee; box-shadow: 0 0 0 1px rgba(10, 26, 51, 0.55);
}
.hook {
  position: absolute; left: -20px; top: calc(var(--drop) - 1px);
  overflow: visible; filter: drop-shadow(0 2px 3px rgba(0, 0, 0, 0.35));
}

.reaction {
  margin: 0 0 14px; padding: 12px 16px; border-radius: 12px;
  text-align: center; font-size: 20px; font-weight: 800; line-height: 1.3;
  animation: reaction-pop 0.35s cubic-bezier(0.2, 0.8, 0.3, 1.25) both;
}
.reaction.hooked {
  color: #ffc2c8; background: rgba(255, 93, 108, 0.14); border: 2px solid var(--red);
  animation-delay: 0.45s; /* appears as the hook bites */
}
.reaction.dodged {
  color: #b8f5d2; background: rgba(61, 220, 132, 0.12); border: 2px solid var(--green);
  animation-delay: 0.35s; /* appears as the card ducks */
}
.reaction.safe {
  color: #b8f5d2; background: rgba(61, 220, 132, 0.12); border: 2px solid var(--green);
}
/* Friendly, not harsh: soft amber, a gentle fade instead of a pop */
.reaction.cautious {
  color: #ffe3a3; background: rgba(255, 209, 102, 0.1);
  border: 2px solid rgba(255, 209, 102, 0.45);
  font-weight: 700; animation-name: reaction-soft; animation-duration: 0.4s;
}
.card.gentle { border-left: 6px solid #ffd166; }
.gentle-tip { margin-bottom: 0; color: #ffe3a3; }

@keyframes reaction-pop {
  0% { opacity: 0; transform: scale(0.85); }
  100% { opacity: 1; transform: scale(1); }
}
@keyframes reaction-soft {
  0% { opacity: 0; transform: translateY(6px); }
  100% { opacity: 1; transform: translateY(0); }
}

@keyframes dot-pop {
  0% { transform: scale(0.6); }
  60% { transform: scale(1.35); }
  100% { transform: scale(1); }
}
@keyframes float-up {
  0% { opacity: 0; transform: translate(-50%, 14px) scale(0.8); }
  18% { opacity: 1; transform: translate(-50%, 0) scale(1.12); }
  100% { opacity: 0; transform: translate(-50%, -96px) scale(1); }
}
@keyframes glow-green {
  0% { box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35); }
  28% { box-shadow: 0 0 0 4px var(--green), 0 0 38px 10px rgba(61, 220, 132, 0.55); }
  100% { box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35); }
}
@keyframes shake {
  10%, 90% { transform: translateX(-3px); }
  20%, 80% { transform: translateX(5px); }
  30%, 50%, 70% { transform: translateX(-9px); }
  40%, 60% { transform: translateX(9px); }
}

/* ---------- Email: looks like an inbox message ---------- */
#message.card { padding: 0; background: none; }
.email {
  background: #f7f9fb; color: #1b2a3a;
  border-radius: 14px; overflow: hidden;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
}
.email::before {
  content: "INBOX";
  display: block; padding: 10px 18px;
  background: #dfe7ee; color: #45566a;
  font-size: 13px; font-weight: 600; letter-spacing: 1px;
}
.email-head {
  display: flex; align-items: flex-start; gap: 12px;
  padding: 14px 16px; border-bottom: 1px solid #e3e9ef;
}
.avatar {
  flex: 0 0 auto; width: 42px; height: 42px; border-radius: 50%;
  background: var(--navy-2); color: #fff;
  display: flex; align-items: center; justify-content: center;
  font-size: 18px; font-weight: 800;
}
.email-who { flex: 1 1 auto; min-width: 0; }
.email-who .from { margin: 0; font-size: 14px; color: #5b6b7b; overflow-wrap: anywhere; }
.email-who .from b { color: #1b2a3a; }
.email-who .subject { margin: 3px 0 0; font-size: 15px; font-weight: 600; color: #1b2a3a; overflow-wrap: anywhere; }
.email-time { flex: 0 0 auto; margin: 2px 0 0; font-size: 12px; color: #7b8a99; white-space: nowrap; }

.email .body { margin: 0; padding: 18px; line-height: 1.6; }

.email-actions {
  display: flex; gap: 10px;
  padding: 12px 16px; border-top: 1px solid #e3e9ef; background: #eef3f7;
}
.email-actions button,
.email-actions button:disabled {
  font-size: 14px; padding: 8px 16px; border-radius: 8px;
  background: #e1e8ee; color: #9aa8b5; border: 1px solid #d3dce4;
  opacity: 1; cursor: not-allowed;
}

/* ---------- Text message: looks like a phone ---------- */
.sms {
  width: 320px; max-width: 100%; margin: 0 auto; padding: 14px 16px 28px;
  background: #101826; border: 3px solid #2b3a4f; border-radius: 36px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
}
.sms::before {
  content: ""; display: block; width: 90px; height: 6px;
  margin: 0 auto 12px; background: #2b3a4f; border-radius: 3px;
}

/* Phone status bar: time, signal bars, battery */
.status-bar {
  display: flex; align-items: center; justify-content: space-between;
  padding: 0 4px 14px; font-size: 13px; font-weight: 600; color: var(--text);
}
.sb-right { display: flex; align-items: center; gap: 7px; }
.signal { display: flex; align-items: flex-end; gap: 2px; height: 11px; }
.signal i { width: 3px; background: var(--text); border-radius: 1px; }
.signal i:nth-child(1) { height: 4px; }
.signal i:nth-child(2) { height: 6px; }
.signal i:nth-child(3) { height: 9px; }
.signal i:nth-child(4) { height: 11px; }
.battery {
  position: relative; width: 25px; height: 13px;
  border: 1.5px solid var(--text); border-radius: 3px; padding: 2px;
}
.battery::after {
  content: ""; position: absolute; right: -4px; top: 3.5px;
  width: 2px; height: 5px; background: var(--text); border-radius: 0 2px 2px 0;
}
.bat-fill { display: block; height: 100%; width: 72%; background: var(--green); border-radius: 1px; }

.sms .label { text-align: center; font-size: 13px; color: var(--muted); margin: 0 0 14px; }
.sms .label b { display: block; font-size: 16px; color: var(--text); }
.bubble {
  background: #e9edf2; color: #1b2a3a;
  padding: 12px 14px; border-radius: 18px 18px 18px 4px;
  line-height: 1.5; margin: 0; max-width: 85%;
}

/* Links are buttons on purpose: they only preview, never open anything */
.link {
  display: flex; flex-wrap: wrap; align-items: center; gap: 6px 10px;
  margin: 0; padding: 0 18px 18px;
}
.link-chip,
.link-chip:hover {
  font: inherit; font-weight: 600; text-align: left;
  padding: 0; margin: 0; border: 0; border-radius: 3px;
  background: none; color: #1a5fd0;
  text-decoration: underline; text-underline-offset: 3px;
  cursor: help; transform: none; box-shadow: none;
  overflow-wrap: anywhere;
}
.link-chip:focus-visible { outline: 2px solid #1a5fd0; outline-offset: 3px; }
.link-hint {
  font-size: 12px; font-weight: 600; color: #7b8a99;
  padding: 2px 8px; border-radius: 999px; background: #e7edf2;
}
.hint-tap { display: none; }
@media (hover: none) {
  .hint-hover { display: none; }
  .hint-tap { display: inline; }
}
.sms .link { padding: 10px 0 0; }
.sms .link-chip { font-family: monospace; font-weight: 400; color: var(--teal); }
.sms .link-chip:focus-visible { outline-color: var(--teal); }
.sms .link-hint { background: #1d2a3d; color: var(--muted); }

/* The popup that shows a link's real destination */
.link-peek {
  position: fixed; z-index: 1000;
  width: max-content; max-width: min(360px, calc(100vw - 24px));
  padding: 10px 12px; border-radius: 10px;
  background: #0d1b2e; color: var(--text);
  border: 1px solid #2b3a4f;
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.45);
  font-size: 13px; line-height: 1.45;
  animation: peek-in 0.12s ease-out;
}
.link-peek p { margin: 0; }
.peek-title { color: var(--muted); font-weight: 600; margin-bottom: 4px !important; }
.peek-url { font-family: monospace; font-size: 14px; overflow-wrap: anywhere; color: #c9d6e2; }
.peek-sub { color: inherit; }
.peek-domain { color: #ffd166; background: rgba(255, 209, 102, 0.12); padding: 0 2px; border-radius: 3px; }
.peek-tip { margin-top: 6px !important; color: var(--muted); font-size: 12px; }
.peek-tip b { color: var(--text); }
@keyframes peek-in {
  from { opacity: 0; transform: translateY(4px); }
}
.link-reveal { margin-bottom: 0; }

.answers { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.answer.phish { background: var(--red); color: white; }
.answer.legit { background: var(--green); color: var(--navy); }

#btn-next, #btn-home { display: block; margin: 0 auto; }
#end-screen { text-align: center; }

/* ---------- Badge reveal ---------- */
.badge-reveal { position: relative; padding: 10px 0 2px; }
.badge-art {
  font-size: 96px; line-height: 1.1;
  animation: badge-drop 1.1s cubic-bezier(0.2, 0.75, 0.3, 1) both;
}
.badge-name {
  margin: 2px 0 0; font-size: 26px; font-weight: 800; color: var(--teal);
  animation: fade-rise 0.5s ease-out 0.75s both;
}
.badge-master {
  display: inline-block; margin: 14px 0 0; padding: 8px 16px;
  border: 2px solid var(--teal); border-radius: 999px;
  background: rgba(45, 224, 196, 0.1);
  font-weight: 700; color: var(--text);
  animation: fade-rise 0.5s ease-out 1.1s both;
}

@keyframes badge-drop {
  0% { opacity: 0; transform: translateY(-170px) scale(0.4) rotate(0deg); }
  55% { opacity: 1; transform: translateY(0) scale(1.28) rotate(360deg); }
  70% { transform: translateY(0) scale(0.92) rotate(372deg); }
  85% { transform: translateY(0) scale(1.07) rotate(354deg); }
  100% { opacity: 1; transform: translateY(0) scale(1) rotate(360deg); }
}
@keyframes fade-rise {
  0% { opacity: 0; transform: translateY(12px); }
  100% { opacity: 1; transform: translateY(0); }
}

/* Confetti burst (pure CSS/JS, no libraries) */
.confetti { position: absolute; left: 0; right: 0; top: 0; height: 0; pointer-events: none; }
.confetti-bit {
  position: absolute; top: 0; width: 9px; height: 14px; border-radius: 2px;
  animation-name: confetti-fall; animation-timing-function: ease-in; animation-fill-mode: forwards;
}
@keyframes confetti-fall {
  0% { opacity: 1; transform: translate(0, -10px) rotate(0deg); }
  100% { opacity: 0; transform: translate(var(--dx), 300px) rotate(var(--rot)); }
}

/* ---------- End of run recap ---------- */
.recap { text-align: left; }
.recap h3 { margin: 0 0 10px; font-size: 16px; color: var(--text); }
.recap ul { margin: 0; padding-left: 20px; }
.recap li { margin: 7px 0; color: var(--muted); line-height: 1.45; }
.recap .count { color: var(--teal); font-weight: 700; }
.recap .clean { margin: 0; font-weight: 600; color: var(--green); }

.leaderboard h3 { margin-top: 0; }
.leaderboard li { margin: 6px 0; }
.leaderboard span { float: right; color: var(--muted); }
.leaderboard .empty { color: var(--muted); list-style: none; margin-left: -20px; }

/* ---------- Phone-sized screens ---------- */
@media (max-width: 430px) {
  header { padding: 20px 14px 6px; }
  header h1 { font-size: 34px; }
  .logo { width: 92px; }
  main { padding: 12px; }

  .mode { padding: 14px 4px; font-size: 14px; }
  .mode small { font-size: 11px; }
  .mission-buttons { flex-direction: column; }
  .mission-buttons button { width: 100%; }

  .dot { width: 12px; height: 12px; }
  .streak { font-size: 13px; }
  .dots { gap: 6px; }
  .run-right { gap: 6px; }
  .contacts-toggle { font-size: 12px; padding: 5px 9px; }
  .contacts-table { font-size: 13px; }
  .pop-score { font-size: 34px; }
  .reaction { font-size: 17px; padding: 10px 12px; margin-bottom: 12px; }

  .email-head { padding: 12px; gap: 10px; }
  .avatar { width: 36px; height: 36px; font-size: 16px; }
  .email-who .subject { font-size: 14px; }
  .email .body { padding: 14px; }
  .link { padding: 0 14px 14px; }
  .email-actions { padding: 10px 12px; }
  .email-actions button, .email-actions button:disabled { padding: 7px 12px; font-size: 13px; }

  .badge-art { font-size: 74px; }
  .badge-name { font-size: 22px; }
}

/* ---------- Respect reduced motion ---------- */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    animation-delay: 0ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
  }
  #message.is-correct .email,
  #message.is-correct .sms { animation: none; box-shadow: 0 0 0 4px var(--green), 0 10px 30px rgba(0, 0, 0, 0.35); }
  #message.is-wrong { animation: none; }
  #message.is-wrong .email,
  #message.is-wrong .sms { box-shadow: 0 0 0 4px var(--red), 0 10px 30px rgba(0, 0, 0, 0.35); }
  .dot.correct, .dot.wrong { animation: none; }
  .reaction { animation: none; }
  .hook-rig { display: none; }
}

/* ---------- Fish cursor (home screen only, see fish-cursor.js) ---------- */
body.fish-mode, body.fish-mode * { cursor: none !important; }
.fish-cursor {
  position: fixed; left: 0; top: 0; z-index: 9999;
  width: 50px; height: 36px; pointer-events: none;
  transform-origin: 46px 18px; opacity: 0;
  transition: opacity 0.2s ease;
  filter: drop-shadow(0 3px 6px rgba(0, 0, 0, 0.35));
}
.fish-cursor svg { display: block; overflow: visible; }
.fish-tail {
  transform-origin: 14px 18px;
  animation: fish-wag var(--wag, 0.6s) ease-in-out infinite alternate;
}
.fish-cursor.gulp svg { animation: fish-gulp 0.3s ease; }
@keyframes fish-wag {
  from { transform: rotate(-16deg); }
  to   { transform: rotate(16deg); }
}
@keyframes fish-gulp {
  40% { transform: scale(1.25, 0.85); }
}
.fish-bubble {
  position: fixed; z-index: 9998; pointer-events: none;
  border-radius: 50%; border: 1.5px solid rgba(185, 255, 241, 0.75);
  background: radial-gradient(circle at 30% 30%, rgba(255, 255, 255, 0.6), rgba(45, 224, 196, 0.08) 60%);
  transform: translate(-50%, -50%);
  animation: bubble-rise 1.2s ease-out forwards;
}
.fish-bubble.burst { animation-duration: 0.8s; }
@keyframes bubble-rise {
  from { opacity: 0.9; transform: translate(-50%, -50%) scale(0.6); }
  to   { opacity: 0; transform: translate(calc(-50% + var(--drift)), calc(-50% - 60px)) scale(1.1); }
}

