input.new_string:
.loading { color: var(--muted); text-align: center; padding: 24px; }

/* ---------- Play layout ---------- */
/* One column by default (phones, narrow windows):
   message, buttons, reaction, result, Next. */
#play-screen { display: flex; flex-direction: column; gap: 12px; }
.play-side { display: contents; }
#play-screen .card { margin: 0; }
.play-side #contacts-panel { order: -1; }   /* opens right under the top bar */
#result h3 { margin-top: 0; }
#result p:last-child, #result ul:last-child { margin-bottom: 0; }

/* Wide screens: two columns, sized so a whole round fits without scrolling */
@media (min-width: 901px) {
  :root { --fit-h: calc(100vh - 100px); }
  @supports (height: 100dvh) { :root { --fit-h: calc(100dvh - 100px); } }

  main { padding-top: 14px; padding-bottom: 14px; }
  #play-screen { flex-direction: row; align-items: flex-start; gap: 24px; }
  .message-wrap { flex: 3 1 0; min-width: 0; }
  .play-side {
    flex: 2 1 0; min-width: 0; max-height: var(--fit-h);
    display: flex; flex-direction: column; gap: 12px;
  }
  .play-side > * { flex: 0 0 auto; }
  .play-side #contacts-panel { order: 0; }
  .contacts-panel .contacts-table th, .contacts-panel .contacts-table td { padding: 6px; }

  /* Long explanations scroll inside the card, so Next stays on screen */
  #result.card { flex: 0 1 auto; min-height: 0; overflow-y: auto; padding: 14px 16px; font-size: 15px; line-height: 1.45; }
  #result ul { padding-left: 20px; margin: 6px 0 10px; }
  #result li { margin: 3px 0; }
  #result p { margin: 8px 0; }

  .answer { padding: 18px; font-size: 18px; }
  .reaction { margin: 0; }
  #btn-next { width: 100%; margin: 0; }

  /* Long messages scroll inside the message, never the page */
  .email, .sms { display: flex; flex-direction: column; max-height: var(--fit-h); }
  .email > *, .sms > * { flex: 0 0 auto; }
  .email .body { flex: 0 1 auto; min-height: 60px; overflow-y: auto; }
  .sms .bubble { flex: 0 1 auto; min-height: 48px; overflow-y: auto; }
}

/* ---------- Run status: progress dots + streak ---------- */
.dots { display: flex; gap: 8px; }

