1	/* PhishSense colors: navy + teal, matching the logo */
2	:root {
3	  --navy: #0a1a33;
4	  --navy-2: #123a5c;
5	  --teal: #2de0c4;
6	  --text: #e9f1f7;
7	  --muted: #9fb7c9;
8	  --red: #ff5d6c;
9	  --green: #3ddc84;
10	}
11	
12	* { box-sizing: border-box; }
13	
14	body {
15	  margin: 0;
16	  font-family: "Inter", Arial, sans-serif;
17	  background: var(--navy);
18	  color: var(--text);
19	}
20	
21	/* ---------- Headers ---------- */
22	/* Big centered header on the home screen */
23	.hero { text-align: center; padding: 32px 16px 8px; }
24	.hero h1 { margin: 0; font-size: 44px; font-weight: 800; }
25	.hero h1 span { color: var(--teal); }
26	.logo { width: 120px; height: auto; display: block; margin: 0 auto 8px; }
27	.tagline { margin: 4px 0 0; color: var(--muted); letter-spacing: 3px; text-transform: uppercase; font-size: 13px; }
28	
29	/* Slim top bar on every other screen */
30	.topbar { display: none; border-bottom: 1px solid rgba(159, 183, 201, 0.15); background: #0c1f3b; }
31	body:not([data-screen="start-screen"]) .hero { display: none; }
32	body:not([data-screen="start-screen"]) .topbar { display: block; }
33	.topbar-inner {
34	  max-width: 1100px; margin: 0 auto; padding: 8px 16px; min-height: 52px;
35	  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px 16px;
36	}
37	.brand { display: flex; align-items: center; gap: 10px; }
38	.brand-logo { width: 36px; height: 36px; display: block; }
39	.brand-name { font-size: 20px; font-weight: 800; }
40	.brand-name span { color: var(--teal); }
41	
42	/* Run status: shown while playing, and as a final summary on the end screen */
43	.run-status { display: none; flex-wrap: wrap; align-items: center; gap: 8px 14px; margin-left: auto; }
44	body[data-screen="play-screen"] .run-status,
45	body[data-screen="end-screen"] .run-status { display: flex; }
46	body[data-screen="end-screen"] .streak,
47	body[data-screen="end-screen"] .contacts-toggle { display: none; }
48	.progress { margin: 0; font-size: 14px; color: var(--muted); white-space: nowrap; }
49	
50	main { max-width: 1100px; margin: 0 auto; padding: 16px; }
51	/* Home, mission, and end screens stay a comfortable reading width */
52	#start-screen, #mission-screen, #end-screen, .leaderboard { max-width: 640px; margin-left: auto; margin-right: auto; }
53	.hidden { display: none !important; }
54	
55	/* Leaderboard: home and end screens only */
56	body:not([data-screen="start-screen"]):not([data-screen="end-screen"]) .leaderboard { display: none; }
57	
58	/* Start screen */
59	.intro { text-align: center; color: var(--muted); margin: 4px 0 0; }
60	.step-label { margin: 22px 0 8px; font-weight: 600; color: var(--text); }
61	.step-label + input { margin-top: 0; }
62	
63	/* Mission screen */
64	.briefing { margin-top: 8px; line-height: 1.6; color: var(--muted); }
65	.briefing p { margin: 0 0 10px; }
66	.briefing p:last-child { margin-bottom: 0; }
67	.briefing b { color: var(--text); }
68	.briefing-title { font-size: 13px; font-weight: 600; letter-spacing: 2px; text-transform: uppercase; color: var(--teal) !important; }
69	.mission-mode { font-size: 20px; font-weight: 800; color: var(--text); }
70	.facts { padding: 10px 14px; border-left: 3px solid var(--teal); background: rgba(45, 224, 196, 0.08); border-radius: 6px; }
71	.mission-buttons { display: flex; justify-content: space-between; gap: 12px; }
72	button.secondary { background: transparent; color: var(--text); border: 2px solid var(--navy-2); }
73	
74	input {
75	  display: block; width: 100%; margin: 0; padding: 12px;
76	  border-radius: 10px; border: 1px solid var(--navy-2);
77	  background: var(--navy-2); color: var(--text); font-size: 16px;
78	}
79	
80	button {
81	  font-family: inherit; font-size: 16px; font-weight: 600; cursor: pointer;
82	  border: none; border-radius: 10px; padding: 12px 18px;
83	  background: var(--teal); color: var(--navy);
84	}
85	button:disabled { opacity: 0.5; cursor: default; }
86	
87	.modes { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
88	.mode { padding: 18px 8px; background: var(--navy-2); color: var(--text); border: 2px solid var(--teal); }
89	.mode small { color: var(--muted); font-weight: 400; }
90	
91	.card { background: var(--navy-2); border-radius: 14px; padding: 18px; margin: 16px 0; }
92	.card.good { border-left: 6px solid var(--green); }
93	.card.bad { border-left: 6px solid var(--red); }
94	
95	.loading { color: var(--muted); text-align: center; padding: 24px; }
96	
97	/* ---------- Play layout ---------- */
98	/* One column by default (phones, narrow windows):
99	   message, buttons, reaction, result, Next. */
100	#play-screen { display: flex; flex-direction: column; gap: 12px; }
101	.play-side { display: contents; }
102	#play-screen .card { margin: 0; }
103	.play-side #contacts-panel { order: -1; }   /* opens right under the top bar */
104	#result h3 { margin-top: 0; }
105	#result p:last-child, #result ul:last-child { margin-bottom: 0; }
106	
107	/* Wide screens: two columns, sized so a whole round fits without scrolling */
108	@media (min-width: 901px) {
109	  :root { --fit-h: calc(100vh - 100px); }
110	  @supports (height: 100dvh) { :root { --fit-h: calc(100dvh - 100px); } }
111	
112	  main { padding-top: 14px; padding-bottom: 14px; }
113	  #play-screen { flex-direction: row; align-items: flex-start; gap: 24px; }
114	  .message-wrap { flex: 3 1 0; min-width: 0; }
115	  .play-side {
116	    flex: 2 1 0; min-width: 0; max-height: var(--fit-h);
117	    display: flex; flex-direction: column; gap: 12px;
118	  }
119	  .play-side > * { flex: 0 0 auto; }
120	  .play-side #contacts-panel { order: 0; }
121	  .contacts-panel .contacts-table th, .contacts-panel .contacts-table td { padding: 6px; }
122	
123	  /* Long explanations scroll inside the card, so Next stays on screen */
124	  #result.card { flex: 0 1 auto; min-height: 0; overflow-y: auto; padding: 14px 16px; font-size: 15px; line-height: 1.45; }
125	  #result ul { padding-left: 20px; margin: 6px 0 10px; }
126	  #result li { margin: 3px 0; }
127	  #result p { margin: 8px 0; }
128	
129	  .answer { padding: 18px; font-size: 18px; }
130	  .reaction { margin: 0; }
131	  #btn-next { width: 100%; margin: 0; }
132	
133	  /* Long messages scroll inside the message, never the page */
134	  .email, .sms { display: flex; flex-direction: column; max-height: var(--fit-h); }
135	  .email > *, .sms > * { flex: 0 0 auto; }
136	  .email .body { flex: 0 1 auto; min-height: 60px; overflow-y: auto; }
137	  .sms .bubble { flex: 0 1 auto; min-height: 48px; overflow-y: auto; }
138	}
139	
140	/* ---------- Run status: progress dots + streak ---------- */
141	.dots { display: flex; gap: 8px; }
142	.dot {
143	  width: 14px; height: 14px; border-radius: 50%;
144	  background: transparent; border: 2px solid #2b4a68;
145	  transition: background 0.25s ease, border-color 0.25s ease, transform 0.25s ease;
146	}
147	.dot.current { border-color: var(--teal); transform: scale(1.2); }
148	.dot.correct { background: var(--green); border-color: var(--green); animation: dot-pop 0.4s ease; }
149	.dot.wrong { background: var(--red); border-color: var(--red); animation: dot-pop 0.4s ease; }
150

