toolUseResult.originalFile:
// Drives headless Chrome over CDP: plays the game at a given viewport and reports
// overflow, centering, peek/button overlap, hook alignment, and saves screenshots.
// usage: node check.mjs <width> <height> <tag> <mode> <win|lose>
import { spawn } from "node:child_process";
import fs from "node:fs";
import path from "node:path";

const [W, H, tag, modeArg, plan] = [Number(process.argv[2]), Number(process.argv[3]), process.argv[4], process.argv[5] || "easy", process.argv[6] || "win"];
const out = path.dirname(new URL(import.meta.url).pathname.replace(/^\/(\w:)/, "$1"));
const port = 9300 + Math.floor(Math.random() * 500);
const prof = path.join(out, `prof-${tag}`);
const chrome = spawn("C:/Program Files/Google/Chrome/Application/chrome.exe",
  ["--headless=new", `--remote-debugging-port=${port}`, `--user-data-dir=${prof}`, "--no-first-run", `--window-size=${W},${H}`, "about:blank"]);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

let targets;
for (let i = 0; i < 50; i++) {
  try { targets = await (await fetch(`http://127.0.0.1:${port}/json`)).json(); break; } catch { await sleep(200); }
}
const page = targets.find((t) => t.type === "page");
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((r) => ws.addEventListener("open", r));
let id = 0; const pending = new Map(); const errors = [];
ws.addEventListener("message", (e) => {
  const m = JSON.parse(e.data);
  if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); }
  if (m.method === "Runtime.exceptionThrown") errors.push(m.params.exceptionDetails.exception?.description);
  if (m.method === "Network.loadingFailed") errors.push("load failed: " + m.params.errorText);
});
const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
const ev = async (expr) => { const r = await send("Runtime.evaluate", { expression: expr, awaitPromise: true, returnByValue: true }); if (r.result.exceptionDetails) throw new Error(JSON.stringify(r.result.exceptionDetails)); return r.result.result.value; };
const shot = async (name) => { const r = await send("Page.captureScreenshot", { format: "png" }); fs.writeFileSync(path.join(out, `${tag}-${name}.png`), Buffer.from(r.result.data, "base64")); };

await send("Emulation.setDeviceMetricsOverride", { width: W, height: H, deviceScaleFactor: 1, mobile: W < 500 });
await send("Page.enable"); await send("Runtime.enable"); await send("Network.enable");
await send("Page.navigate", { url: "http://localhost:5174/" });
await sleep(2000);

// Overflow + horizontal centering of the screen's visible content
const measure = (sel) => ev(`(() => {
  const els = ${JSON.stringify(sel)}.map((s) => document.querySelector(s)).filter((e) => e && e.offsetParent);
  const rs = els.map((e) => e.getBoundingClientRect());
  const L = Math.min(...rs.map((r) => r.left)), R = Math.max(...rs.map((r) => r.right));
  return { screen: document.body.dataset.screen, doc: document.documentElement.scrollHeight, view: innerHeight,
    fits: document.documentElement.scrollHeight <= innerHeight, overX: document.documentElement.scrollWidth > innerWidth,
    leftGap: Math.round(L), rightGap: Math.round(innerWidth - R), width: Math.round(R - L),
    bootstrap: getComputedStyle(document.querySelector('.row')).display };
})()`);

console.log("home", JSON.stringify(await measure([".home-col"])));
await shot("0-home");

await ev(`document.getElementById('username').value='Tester'; document.querySelector('.mode[data-mode="${modeArg}"]').click()`);
await sleep(300);
console.log("mission", JSON.stringify(await measure(["#mission-screen .home-col"])));
await shot("1-mission");
await ev(`document.getElementById('btn-start').click()`);

for (let r = 0; r < 5; r++) {
  await sleep(700);
  const before = await measure(["#message", ".answers"]);
  const peek = await ev(`(() => {
    const chip = document.querySelector('.link-chip'); if (!chip) return 'no link';
    chip.dispatchEvent(new MouseEvent('mouseover', { bubbles: true }));
    const p = document.getElementById('link-peek').getBoundingClientRect();
    const hit = [...document.querySelectorAll('.answer')].some((b) => { const q = b.getBoundingClientRect(); return !(p.right <= q.left || p.left >= q.right || p.bottom <= q.top || p.top >= q.bottom); });
    return { coversButtons: hit };
  })()`);
  if (peek !== "no link") await shot(`2-round${r + 1}-peek`);
  await ev(`(() => { const c = document.querySelector('.link-chip'); c && c.dispatchEvent(new MouseEvent('mouseout', { bubbles: true, relatedTarget: document.body })); })()`);

  // Round 2: open trusted contacts before answering
  if (r === 1) await ev(`document.getElementById('btn-contacts').click()`);

  // "win": right on all but round 1 (wrong on purpose to see the hook). "lose": all wrong.
  const guess = await ev(`(() => { const s = MOCK_SCENARIOS.find((x) => x.scenario_id === current.scenario_id);
    const right = s.game_answer; const wrong = right === 'Phish' ? 'Legit' : 'Phish';
    return ${plan === "win" ? "(" + r + " === 0 ? wrong : right)" : "wrong"}; })()`);
  await ev(`window.__rig = null; new MutationObserver((ms) => ms.forEach((m) => m.addedNodes.forEach((n) => { if (n.classList && n.classList.contains('hook-rig')) { const card = document.getElementById('message').firstElementChild.getBoundingClientRect(); window.__rig = { offCenter: Math.round(parseFloat(n.style.left) - scrollX - (card.left + card.width/2)), hookAboveCardTop: Math.round(card.top - parseFloat(n.style.getPropertyValue('--drop')) - scrollY) }; } }))).observe(document.body, { childList: true }); document.getElementById('btn-${guess.toLowerCase()}').click()`);
  await sleep(450);
  if (r === 0) await shot(`3-round1-mid-anim`);
  await sleep(1700);
  const after = await measure(["#message", ".answers"]);
  const info = await ev(`({ guess: '${guess}', reaction: document.getElementById('reaction').className.replace('reaction ', ''), rig: window.__rig,
    nextVisible: (() => { const b = document.getElementById('btn-next').getBoundingClientRect(); return b.bottom <= innerHeight; })(),
    msgTop: Math.round(document.getElementById('message').getBoundingClientRect().top), btnTop: Math.round(document.querySelector('.answers').getBoundingClientRect().top),
    counter: document.getElementById('progress').textContent, streak: document.getElementById('streak').textContent,
    streakShown: getComputedStyle(document.getElementById('streak')).display !== 'none',
    channel: document.querySelector('#message .sms') ? 'sms' : 'email' })`);
  console.log(`round ${r + 1}`, JSON.stringify({ before: { fits: before.fits, leftGap: before.leftGap, rightGap: before.rightGap }, after: { fits: after.fits, doc: after.doc }, peek, ...info }));
  await shot(`4-round${r + 1}-answered`);
  if (r === 1) await ev(`document.getElementById('btn-contacts').click()`);
  await ev(`document.getElementById('btn-next').click()`);
}
await sleep(2500);
console.log("end", JSON.stringify(await measure([".end-main", ".end-side"])));
await shot("5-end");
await ev(`document.getElementById('btn-home').click()`);
await sleep(300);
console.log("home again", JSON.stringify(await ev(`({ screen: document.body.dataset.screen, boardRows: document.querySelector('#start-screen .leaderboard-list').children.length })`)));

console.log("errors", JSON.stringify(errors));
ws.close(); chrome.kill();
await sleep(500);
try { fs.rmSync(prof, { recursive: true, force: true }); } catch {}
process.exit(0);

